/* Returns { text, gist } or null. gist = built from AI labels when the exact sentence isn't in the offline table. */
function swOf(r, field) {
  const text = field === "favorite" ? r.favorite : r.better;
  if (!text || r.lang === "sw") return null;
  const exact = SW_TR[text.trim()];
  if (exact) return { text: exact };
  if (r.lang === "other") return { text: "Tafsiri haipatikani kwa lugha hii. Muulize mwongozo wako.", gist: true };
  const parts = (r.labels || []).filter((l) => l.field === field).map((l) => SW_GIST[l.topic + ":" + l.feeling]).filter(Boolean);
  if (parts.length) return { text: [...new Set(parts)].join(" "), gist: true };
  return { text: "Tafsiri haipatikani kwenye simu hii. Muulize mwongozo wako.", gist: true };
}

