const MONTHS = { en: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
  sw: ["Januari", "Februari", "Machi", "Aprili", "Mei", "Juni", "Julai", "Agosti", "Septemba", "Oktoba", "Novemba", "Desemba"] };
const MON_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function fmt(s, vars) { return String(s).replace(/\{(\w+)\}/g, (_, k) => (vars && vars[k] != null ? vars[k] : "")); }
function li(l) { return l === "sw" ? 1 : 0; }
function keyTitle(key, l) {
  if (KEY_TITLE[key]) return KEY_TITLE[key][l];
  const t = key.split(":")[0];
  return (TOPIC_NAME[t] || TOPIC_NAME.other)[l];
}
function libFor(key, l) {
  const e = LIB[key]; const i = li(l); const name = keyTitle(key, l);
  if (e) return { summary: e.s[i], suggestion: e.g[i], plan: e.p[i] };
  return { summary: l === "sw" ? `Wageni walitaja ${name.toLowerCase()}.` : `Visitors mentioned ${name.toLowerCase()}.`,
    suggestion: l === "sw" ? "Zungumza na mwongozo wako na uamue cha kubadilisha." : "Talk it over with your guide and decide what to change.",
    plan: l === "sw" ? `Angalia: ${name}` : `Look into: ${name}` };
}
function shortDate(iso) { const [, m, d] = iso.split("-").map(Number); return `${MON_SHORT[m - 1]} ${d}`; }

/* ---------- Simulated on-device classifier ---------- */
function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
function findKeyword(text, kws) {
  if (!text) return null;
  for (const kw of kws) {
    const re = new RegExp("(^|[^\\p{L}])(" + escapeRe(kw) + "[\\p{L}]*)", "iu");
    const m = text.match(re);
    if (m) return m[2];
  }
  return null;
}
function classify(r) {
  const out = { ...r };
  if (r.manualLabels) { out.labels = r.manualLabels; out.status = "analyzed"; return out; }
  if (r.lang === "other") { out.labels = []; out.status = r.checked ? "checked" : "not_sure"; out.reason = "unsupported_language"; return out; }
  const labels = [];
  for (const [topic, kws] of Object.entries(KEYWORDS)) {
    const fp = findKeyword(r.favorite, kws);
    if (fp) labels.push({ topic, feeling: "positive", phrase: fp, field: "favorite", confidence: 0.8 + ((r.seq * 7) % 15) / 100 });
    const bp = findKeyword(r.better, kws);
    if (bp) labels.push({ topic, feeling: topic === "buy_coffee" ? "request" : "negative", phrase: bp, field: "better", confidence: 0.8 + ((r.seq * 3) % 15) / 100 });
  }
  if (!labels.length) { out.labels = []; out.status = r.checked ? "checked" : "not_sure"; out.reason = "low_confidence"; out.confidence = 0.38 + (r.seq % 10) / 100; return out; }
  out.labels = labels; out.status = "analyzed"; return out;
}
function keysOf(r) { const s = new Set(); (r.labels || []).forEach((l) => s.add(l.topic + ":" + l.feeling)); return [...s]; }

/* ---------- Seed plans ---------- */
function seedState(seedReviews) {
  const maxSeq = Math.max(...seedReviews.map((r) => r.seq));
  return {
    reviews: seedReviews.map((r) => ({ ...r })),
    plans: [
      { id: "p1", key: "path:negative", status: "trying", startedAt: "2025-10-31", seqAt: maxSeq, beforeCount: 4, beforeTotal: 7 },
      { id: "p2", key: "roasting:positive", status: "trying", startedAt: "2025-10-31", seqAt: maxSeq, beforeCount: 6, beforeTotal: 7 },
      { id: "p3", key: "buy_coffee:request", status: "saved", startedAt: "2025-10-31", seqAt: maxSeq, beforeCount: 3, beforeTotal: 7 },
      { id: "p4", key: "price:negative", status: "done", startedAt: "2025-09-12", seqAt: 20, beforeCount: 3, beforeTotal: 14 },
    ],
    ignored: [], seq: maxSeq, lastSeenSeq: maxSeq, pending: 0, dashLang: "en",
  };
}

