function Pin({ ctx }) {
  const { t } = ctx; const [dig, setDig] = useState(""); const [err, setErr] = useState(false); const [shake, setShake] = useState(false);
  const [tries, setTries] = useState(0); const [lockLeft, setLockLeft] = useState(0); const [ok, setOk] = useState(false);
  useEffect(() => { if (lockLeft <= 0) return; const id = setTimeout(() => setLockLeft((x) => x - 1), 1000); return () => clearTimeout(id); }, [lockLeft]);
  const press = (k) => { if (lockLeft || ok) return; vib(6); setErr(false); if (k === "del") setDig((d) => d.slice(0, -1)); else setDig((d) => (d.length < 4 ? d + k : d)); };
  const enter = () => {
    if (dig === "0000") { setOk(true); setTimeout(() => { ctx.setUnlocked(true); ctx.go("home"); }, 160); return; }
    vib([30, 40, 30]); setErr(true); setShake(true); setTimeout(() => setShake(false), 320);
    const n = tries + 1; setTries(n); setTimeout(() => setDig(""), 600); if (n >= 5) { setLockLeft(30); setTries(0); }
  };
  const keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "", "0", "del"];
  return html`<div class="scr"><div class="scroll pin">
    <${Logo} h=${64} alt="" /><h1 class="h1">${t(ctx.loggedIn ? "pinTitle" : "pinTitleDash")}</h1><p class="sec">${t("pinPrompt")}</p>
    <div class=${"pinboxes" + (shake ? " shake" : "")} aria-live="polite" aria-label=${"Digit " + dig.length + " of 4 entered"}>
      ${[0, 1, 2, 3].map((i) => html`<span key=${i} class=${"pinbox" + (i === dig.length && !ok ? " next" : "") + (err ? " err" : "") + (ok ? " ok" : "")}>${i < dig.length ? html`<span class="pindot"></span>` : null}</span>`)}
    </div>
    <div class="pinmsg">${lockLeft ? html`<span class="errmsg" role="alert"><${Icon} n="alert" s=${16} />${t("pinLocked", { n: lockLeft })}</span>` : err ? html`<span class="errmsg" role="alert"><${Icon} n="alert" s=${16} />${t("pinWrong")}</span>` : null}</div>
    <div class="keypad">${keys.map((k, i) => k === "" ? html`<span key=${i}></span>` :
      html`<button key=${i} class="key" disabled=${!!lockLeft} onClick=${() => press(k)} aria-label=${k === "del" ? t("delDigit") : k}>${k === "del" ? html`<${Icon} n="del" s=${24} />` : k}</button>`)}</div>
    <button class="btn btn-primary" disabled=${dig.length < 4 || !!lockLeft} onClick=${enter}>${t("enter")}</button>
    ${ctx.loggedIn ? html`<p class="cap center tertiary">${t("demoPin")}</p>` : null}
  </div></div>`;
}
